import{_ as p,a0 as r,w as s,s as m,ao as l,I as a,x as t,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第三節 總結） | LCTT x X-CMD","titleTemplate":false,"description":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第三節 總結） | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第三節 總結） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第三節 總結） | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150716 A Week With GNOME As My Linux Desktop--What They Get Right & Wrong - Page 5 - Conclusion","title":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第三節 總結）","tag":"201508","desc":""},"relativePath":"201508/20150716 A Week With GNOME As My Linux Desktop--What They Get Right & Wrong - Page 5 - Conclusion.md","filePath":"[post].md"}'),G={name:"201508/20150716 A Week With GNOME As My Linux Desktop--What They Get Right & Wrong - Page 5 - Conclusion.md"};function u(D,e,E,d,h,g){const o=r("Link");return s(),m("div",null,[e[11]||(e[11]=l('<h1 id="一週-gnome-之旅-品味它和-kde-的是是非非-第三節-總結" tabindex="-1">一週 GNOME 之旅：品味它和 KDE 的是是非非（第三節 總結） <a class="header-anchor" href="#一週-gnome-之旅-品味它和-kde-的是是非非-第三節-總結" aria-label="Permalink to “一週 GNOME 之旅：品味它和 KDE 的是是非非（第三節 總結）”">​</a></h1><h3 id="用户體驗和最後想法" tabindex="-1">用户體驗和最後想法 <a class="header-anchor" href="#用户體驗和最後想法" aria-label="Permalink to “用户體驗和最後想法”">​</a></h3><p>當 Gnome 2.x 和 KDE 4.x 要正面交鋒時……我在它們之間左右逢源。我對它們愛恨交織，但總的來説它們使用起來還算是一種樂趣。然後 Gnome 3.x 來了，帶着一場 Gnome Shell 的戲劇。那時我就放棄了 Gnome，我盡我所能的避開它。當時它對用户是不友好的，而且不直觀，它打破了原有的設計典範，只為平板的統治世界做準備……而根據平板下跌的銷量來看，這樣的未來不可能實現。</p><p>在 Gnome 3 後續發佈了八個版本後，奇蹟發生了。Gnome 變得對對用户友好了，變得直觀了。它完美嗎？當然不。我還是很討厭它想推動的那種設計範例，我討厭它總想給我強加一種工作流（work flow），但是在付出時間和耐心後，這兩都能被接受。只要你能夠回頭去看看 Gnome Shell 那外星人一樣的界面，然後開始跟 Gnome 的其它部分（特別是控制中心）互動，你就能發現 Gnome 絕對做對了：細節，對細節的關注！</p><p>人們能適應新的界面設計範例，能適應新的工作流—— iPhone 和 iPad 都證明了這一點——但真正讓他們操心的一直是“紙割”——那些不完美的細節。</p><p>它帶出了 KDE 和 Gnome 之間最重要的一個區別。Gnome 感覺像一個產品，像一種非凡的體驗。你用它的時候，覺得它是完整的，你要的東西都觸手可及。它讓人感覺就像是一個擁有 Windows 或者 OS X 那樣桌面體驗的 Linux 桌面版：你要的都在裏面，而且它是被同一個目標一致的團隊中的同一個人寫出來的。天，即使是一個應用程序發出的 sudo 請求都感覺是 Gnome 下的一個特意設計的部分，就像在 Windows 下的一樣。而在 KDE 下感覺就是隨便一個應用程序都能創建的那種各種外觀的彈窗。它不像是以系統本身這樣的正式身份停下來説“嘿，有個東西要請求管理員權限！你要給它嗎？”。</p><p>KDE 讓人體驗不到有凝聚力的體驗。KDE 像是在沒有方向地打轉，感覺沒有完整的體驗。它就像是一堆東西往不同的的方向移動，只不過恰好它們都有一個共同享有的工具包而已。如果開發者對此很開心，那麼好吧，他們開心就好，但是如果他們想提供最好體驗的話，那麼就需要多關注那些小地方了。用户體驗跟直觀應當做為每一個應用程序的設計中心，應當有一個視野，知道 KDE 要提供什麼——並且——知道它看起來應該是什麼樣的。</p><p>是不是有什麼原因阻止我在 KDE 下使用 Gnome 磁盤管理？ Rhythmbox 呢? Evolution 呢? 沒有，沒有，沒有。但是這樣説又錯過了關鍵。Gnome 和 KDE 都稱它們自己為“桌面環境”。那麼它們就應該是完整的環境，這意味着他們的各個部件應該彙集並緊密結合在一起，意味着你應該使用它們環境下的工具，因為它們説“您在一個完整的桌面中需要的任何東西，我們都支持。”説真的？只有 Gnome 看起來能符合完整的要求。KDE 在“彙集在一起”這一方面感覺就像個半成品，更不用説提供“完整體驗”中你所需要的東西。Gnome 磁盤管理沒有相應的對手—— kpartionmanage 要求 ROOT 權限。KDE 不運行“首次用户註冊”的過程（原文：No &#39;First Time User&#39; run through。可能是指系統安裝過程中KDE沒有創建新用户的過程，譯註） ，現在也不過是在 Kubuntu 下引入了一個用户管理器。老天，Gnome 甚至提供了地圖、筆記、日曆和時鐘應用。這些應用都是百分百要緊的嗎？不，當然不了。但是正是這些應用幫助 Gnome 推動“Gnome 是一種完整豐富的體驗”的想法。</p><p>我吐槽的 KDE 問題並非不可能解決，決對不是這樣的！但是它需要人去關心它。它需要開發者為他們的作品感到自豪，而不僅僅是為它們實現的功能而感到自豪——組織的價值可大了去了。別奪走用户設置選項的能力—— GNOME 3.x 就是因為缺乏配置選項的能力而為我所詬病，但別把“好吧，你想怎麼設置就怎麼設置”作為藉口而不提供任何理智的默認設置。默認設置是用户將看到的東西，它們是用户從打開軟件的第一刻開始進行評判的關鍵。給用户留個好印象吧。</p><p>我知道 KDE 開發者們知道設計很重要，這也是為什麼VDG（Visual Design Group 視覺設計組）存在的原因，但是感覺好像他們沒有讓 VDG 充分發揮，所以 KDE 裏存在組織上的缺陷。不是 KDE 沒辦法完整，不是它沒辦法彙集整合在一起然後解決衰敗問題，只是開發者們沒做到。他們瞄準了靶心……但是偏了。</p><p>還有，在任何人説這句話之前……千萬別説“歡迎給我們提交補丁啊&quot;。因為當我開心的為某個人提交補丁時，只要開發者堅持以他們喜歡的卻不直觀的方式幹事，更多這樣的煩人事就會不斷發生。這不關 Muon 有沒有中心對齊。也不關 Amarok 的界面太醜。也不關每次我敲下快捷鍵後，彈出的音量和亮度調節窗口占用了我一大塊的屏幕“地皮”（説真的，有人會把這些東西縮小）。</p><p>這跟心態的冷漠有關，跟開發者們在為他們的應用設計 UI 時根本就不多加思考有關。KDE 團隊做的東西都工作得很好。Amarok 能播放音樂。Dragon 能播放視頻。Kwin 或 Qt 和 kdelibs 似乎比 Mutter/gtk 更有力更效率（僅根據我的電池電量消耗計算。非科學性測試）。這些都很好，很重要……但是它們呈現的方式也很重要。甚至可以説，呈現方式是最重要的，因為它是用户看到的並與之交互的東西。</p><p>KDE 應用開發者們……讓 VDG 參與進來吧。讓 VDG 審查並核准每一個“核心”應用，讓一個 VDG 的 UI/UX 專家來設計應用的使用模式和使用流程，以此保證其直觀性。真見鬼，不管你們在開發的是啥應用，僅僅把它的模型發到 VDG 論壇尋求反饋甚至都可能都能得到一些非常好的指點跟反饋。你有這麼好的資源在這，現在趕緊用吧。</p><p>我不想説得好像我一點都不懂感恩。我愛 KDE，我愛那些志願者們為了給 Linux 用户一個可視化的桌面而付出的工作與努力，也愛可供選擇的 Gnome。正是因為我關心我才寫這篇文章。因為我想看到更好的 KDE，我想看到它走得比以前更加遙遠。而這樣做需要每個人繼續努力，並且需要人們不再躲避批評。它需要人們對系統互動及系統崩潰的地方都保持誠實。如果我們不能直言批評，如果我們不説“這真垃圾！”，那麼情況永遠不會變好。</p><p>這周後我會繼續使用 Gnome 嗎？可能不。應該不。Gnome 還在試着強迫我接受其工作流，而我不想追隨，也不想遵循，因為我在使用它的時候感覺變得不夠高效，因為它並不遵循我的思維模式。可是對於我的朋友們，當他們問我“我該用哪種桌面環境？”我可能會推薦 Gnome，特別是那些不大懂技術，只要求“能工作”就行的朋友。根據目前 KDE 的形勢來看，這可能是我能説出的最狠毒的評估了。</p><hr>',16)),a("p",null,[e[1]||(e[1]=t("via: ",-1)),n(o,{href:"http://www.phoronix.com/scan.php?page=article&item=gnome-week-editorial&num=5"},{default:i(()=>[...e[0]||(e[0]=[t("http://www.phoronix.com/scan.php?page=article&item=gnome-week-editorial&num=5",-1)])]),_:1})]),a("p",null,[e[4]||(e[4]=t("作者：Eric Griffith 譯者：",-1)),n(o,{href:"https://github.com/XLCYun"},{default:i(()=>[...e[2]||(e[2]=[t("XLCYun",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:i(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),n(o,{href:"https://linux.cn/"},{default:i(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const x=p(G,[["render",u]]);export{_ as __pageData,x as default};
